"use client";

/**
 * Post-signup profile collection for a Tide app (generated by the Tide MCP `tide_onboarding`, then restyled).
 * Tide's IdP asserts only a username (the vuid): no email, no name. We collect ONE field, a display name,
 * stored as `firstName`, through the Account API with the USER'S OWN token (never the Admin API, so it is not
 * captured as an IGA change request). It is dismissible, and it never invents a placeholder email (AP-85).
 */

import { useEffect, useState } from "react";
import { useTideCloak } from "@tidecloak/nextjs";

const DISMISS_KEY = "tide.profile-onboarding.dismissed";

type Props = {
  baseUrl: string;
  realm: string;
  onDone?: () => void;
};

export function ProfileOnboarding({ baseUrl, realm, onDone }: Props) {
  const { authenticated, getValueFromToken, secureFetch } = useTideCloak();
  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!authenticated) return;
    if (localStorage.getItem(DISMISS_KEY) === "1") return;
    // getValueFromToken(key), NOT tokenParsed (it does not exist on the context and fails silently).
    const hasName = getValueFromToken("given_name") || getValueFromToken("name");
    if (!hasName) {
      setName((getValueFromToken("given_name") as string) || "");
      setOpen(true);
    }
  }, [authenticated, getValueFromToken]);

  if (!open) return null;

  const dismiss = () => {
    localStorage.setItem(DISMISS_KEY, "1");
    setOpen(false);
    onDone?.();
  };

  async function save() {
    setBusy(true);
    setError(null);
    try {
      const res = await secureFetch(`${baseUrl}/realms/${realm}/account/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ firstName: name.trim() }),
      });
      if (res.status === 401 || res.status === 403) throw new Error("Not authorised to update your profile.");
      if (res.status === 202) throw new Error("Your change was queued for approval and is not saved yet.");
      if (!res.ok) throw new Error(`Could not save your name (${res.status}).`);
      setOpen(false);
      onDone?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Something went wrong.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="modal-bg" role="dialog" aria-modal="true" aria-labelledby="onb-title">
      <div className="modal">
        <h2 id="onb-title">Welcome to KinKey</h2>
        <p className="muted small" style={{ marginTop: 6 }}>
          Optional. You can skip this.
        </p>
        <label className="field" htmlFor="onb-name">
          What should we call you?
        </label>
        <input
          id="onb-name"
          className="input"
          value={name}
          onChange={(e) => setName(e.target.value)}
          autoComplete="given-name"
          placeholder="e.g. Mom"
        />
        {error && (
          <p role="alert" className="small" style={{ color: "var(--red)", marginTop: 10 }}>
            {error}
          </p>
        )}
        <div className="row" style={{ justifyContent: "flex-end", marginTop: 20 }}>
          <button type="button" className="btn btn-ghost" onClick={dismiss} disabled={busy}>
            Not now
          </button>
          <button type="button" className="btn btn-primary" onClick={save} disabled={busy || !name.trim()}>
            {busy ? "Saving…" : "Save"}
          </button>
        </div>
      </div>
    </div>
  );
}
